#include <iostream>
#include <map>
#include <vector>
#include <cstring>
using namespace std;

#define ll long long int
#define MOD 1000000007LL

ll n, k;
ll ans[55][55][55];

ll max(ll a, ll b) {
    if (a > b) return a;
    return b;
}

int dy[] = {-1, 0, 1};

int main() {
    cin >> n >> k;
    memset(ans, 0, sizeof(ans));

    ans[1][0][0] = 1;

    for (ll i = 2; i <= n; i++) {
        for (ll x1 = 0; x1 <= (i - 1) / 2; x1++) {
            for (ll j = 0; j < 3; j++) {
                ll y1 = x1 + dy[j];
                if (y1 < 0) continue;

                ll x = y1 + 1;
                ll y = max(x1, y1);

                ans[i][x][y] += ans[i - 1][x1][y1] * (i - 1);
                ans[i][x][y] %= MOD;
            }
        }

        for (ll z = 1; z <= (i - 1) / 2; z++) {
            for (ll x1 = 0; x1 <= z / 2; x1++) {
                for (ll x2 = 0; x2 <= (i - 1 - z) / 2; x2++) {
                    for (ll j1 = 0; j1 < 3; j1++) {
                        ll y1 = x1 + dy[j1];
                        if (y1 < 0) continue;

                        for (ll j2 = 0; j2 < 3; j2++) {
                            ll y2 = x2 + dy[j2];
                            if (y2 < 0) continue;

                            ll x = max(1 + x1 + y2, 1 + x2 + y1);
                            ll y = max(x1, y1) + max(x2, y2);

                            ll delta = ans[z][x1][y1] *
                                       ans[i - 1 - z][x2][y2];
                            delta %= MOD;

                            ll q = (i - 1) * (i - 2);
                            if (z == i - 1 - z) q /= 2;

                            delta *= q;
                            delta %= MOD;

                            ans[i][x][y] += delta;
                            ans[i][x][y] %= MOD;
                        }
                    }
                }
            }
        }
    }

    ll res = ans[n][k - 1][k] + ans[n][k][k] + ans[n][k][k - 1];
    cout << res << endl;

    return 0;
}

